"""Entry point for the deterministic ticket retry simulation."""

from ticket_tool import TicketTool

MAX_ATTEMPTS = 3


def scenario(data):
    operation_id = data["operation_id"]
    ticket = data["ticket"]
    fault_sequence = data.get("fault_sequence", [])

    if not isinstance(operation_id, str) or not operation_id:
        raise ValueError("operation_id must be a non-empty string")
    if not isinstance(ticket, dict):
        raise ValueError("ticket must be an object")

    title = ticket.get("title")
    description = ticket.get("description")
    if not isinstance(title, str) or not title:
        raise ValueError("ticket.title must be a non-empty string")
    if not isinstance(description, str) or not description:
        raise ValueError("ticket.description must be a non-empty string")

    if not isinstance(fault_sequence, list):
        raise ValueError("fault_sequence must be an array")
    if len(fault_sequence) > MAX_ATTEMPTS:
        raise ValueError("fault_sequence length cannot exceed 3")

    valid_outcomes = {"success", "temporary_error", "write_then_lost"}
    for item in fault_sequence:
        if item not in valid_outcomes:
            raise ValueError("invalid fault_sequence item: %r" % (item,))

    tool = TicketTool()
    actual_calls = 0

    for attempt in range(1, MAX_ATTEMPTS + 1):
        if attempt <= len(fault_sequence):
            outcome = fault_sequence[attempt - 1]
        else:
            outcome = "success"

        result = tool.call(operation_id, ticket, outcome, attempt)
        actual_calls += 1

        if result["status"] == "success":
            return {
                "status": "success",
                "actual_calls": actual_calls,
                "records": list(tool.records),
            }

        if result["status"] in ("temporary_error", "lost_after_write"):
            continue

    return {
        "status": "failure",
        "actual_calls": actual_calls,
        "records": list(tool.records),
    }

