"""Deterministic local ticket tool used by the retry simulation."""


class TicketTool:
    def __init__(self):
        self.records = []
        self._by_operation = {}

    def _new_record(self, operation_id, ticket, attempt):
        return {
            "ticket_id": "ticket-%s-%s" % (operation_id, attempt),
            "operation_id": operation_id,
            "title": ticket["title"],
            "description": ticket["description"],
        }

    def _record_success(self, operation_id, ticket, attempt):
        existing = self._by_operation.get(operation_id)
        if existing is not None:
            return existing

        record = self._new_record(operation_id, ticket, attempt)
        self.records.append(record)
        self._by_operation[operation_id] = record
        return record

    def _record_write_then_lost(self, operation_id, ticket, attempt):
        # Main fault: write the ticket but deliberately do not register
        # the operation_id in the idempotency store. A later success attempt
        # therefore creates another record for the same logical operation.
        record = self._new_record(operation_id, ticket, attempt)
        self.records.append(record)
        return record

    def call(self, operation_id, ticket, outcome, attempt):
        if outcome == "temporary_error":
            return {"status": "temporary_error"}

        if outcome == "write_then_lost":
            record = self._record_write_then_lost(operation_id, ticket, attempt)
            return {"status": "lost_after_write", "record": record}

        record = self._record_success(operation_id, ticket, attempt)
        return {"status": "success", "record": record}

