import hashlib
import os
import tempfile

from storage import PersistentStore
from workflow import Workflow

_STEPS = ("prepare", "transform", "generate")


def _file_path(instance_id):
    digest = hashlib.sha256(("batch-workflow:" + instance_id).encode("utf-8")).hexdigest()[:24]
    return os.path.join(tempfile.gettempdir(), "batch_wf_" + digest + ".json")


def _normalise_actions(raw_actions):
    actions = []
    if not isinstance(raw_actions, list):
        return actions
    for raw in raw_actions:
        if not isinstance(raw, dict):
            continue
        action = raw.get("action", "resume")
        if action not in ("run", "resume"):
            action = "resume"
        stop_after = raw.get("stop_after", "none")
        if stop_after not in ("none", "prepare", "transform"):
            stop_after = "none"
        actions.append({"action": action, "stop_after": stop_after})
    return actions


def scenario(data):
    data = data if isinstance(data, dict) else {}
    instance_id = str(data.get("instance_id", "default"))
    file_path = _file_path(instance_id)
    actions = _normalise_actions(data.get("actions"))

    for action in actions:
        store = PersistentStore(file_path)
        workflow = Workflow(store, instance_id)
        workflow.execute(action["action"], action["stop_after"])

    store = PersistentStore(file_path)
    counts = {}
    for record in store.records:
        step = record.get("step")
        if step in _STEPS:
            counts[step] = counts.get(step, 0) + 1

    duplicate_counts = {
        step: max(0, counts.get(step, 0) - 1)
        for step in _STEPS
    }
    status = {
        step: store.status.get(step, "pending")
        for step in _STEPS
    }

    return {
        "records": store.records,
        "status": status,
        "duplicate_counts": duplicate_counts,
    }

