class Workflow:
    STEPS = ("prepare", "transform", "generate")

    def __init__(self, store, instance_id):
        self.store = store
        self.instance_id = instance_id

    def execute(self, action, stop_after):
        # Intentionally ignores persisted status: every step is always executed.
        for step in self.STEPS:
            self.store.add_record(self.instance_id, step)
            if stop_after == step:
                break
        self.store.save()

