import json
import os


class PersistentStore:
    _STEPS = ("prepare", "transform", "generate")

    def __init__(self, filepath):
        self.filepath = filepath
        self.records = []
        self.status = {"prepare": "pending", "transform": "pending", "generate": "pending"}
        self.load()

    def load(self):
        data = None
        try:
            with open(self.filepath, "r", encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError):
            data = None

        if isinstance(data, dict):
            records = data.get("records", [])
            if isinstance(records, list):
                self.records = [r for r in records if isinstance(r, dict)]
            status = data.get("status", {})
            if isinstance(status, dict):
                for step in self._STEPS:
                    self.status[step] = "completed" if status.get(step) == "completed" else "pending"

    def save(self):
        data = {
            "status": self.status,
            "records": self.records,
        }
        tmp_path = self.filepath + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
        os.replace(tmp_path, self.filepath)

    def add_record(self, instance_id, step):
        self.records.append({
            "sequence": len(self.records) + 1,
            "instance_id": instance_id,
            "step": step,
        })
        self.status[step] = "completed"
        self.save()

